["text"] = "|Hchannel:RAID|h[Raid]|h |Hplayer:Patodk-Zul'jin:207:RAID:|h[|cffc41e3aPatodk-Zul'jin|r]|h: anyone can share q",
["timestamp"] = 1787674500,
